import * as React from "react";
import { cn } from "../lib/utils";
import { Separator } from "./separator";

type CardSize = "default" | "sm";

const CardSizeContext = React.createContext<CardSize>("default");

const cardSpacing = {
  default: {
    root: "gap-4 py-4",
    section: "px-4",
    footer: "p-4",
    footerSeparator: "-mb-4",
    headerBorder: "[.border-b]:pb-4",
  },
  sm: {
    root: "gap-3 py-3",
    section: "px-3",
    footer: "p-3",
    footerSeparator: "-mb-3",
    headerBorder: "[.border-b]:pb-3",
  },
} as const;

function Card({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"div"> & { size?: CardSize }) {
  return (
    <CardSizeContext.Provider value={size}>
      <div
        data-slot="card"
        data-size={size}
        className={cn(
          "group/card flex flex-col overflow-hidden rounded-xl border surface-panel text-sm text-card-foreground has-data-[slot=card-footer]:pb-0 has-[>img:first-child]:pt-0 *:[img:first-child]:rounded-t-xl *:[img:last-child]:rounded-b-xl",
          cardSpacing[size].root,
          className,
        )}
        {...props}
      />
    </CardSizeContext.Provider>
  );
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  const size = React.useContext(CardSizeContext);

  return (
    <div
      data-slot="card-header"
      className={cn(
        "group/card-header @container/card-header grid auto-rows-min items-start gap-1 rounded-t-xl has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto]",
        cardSpacing[size].section,
        cardSpacing[size].headerBorder,
        className,
      )}
      {...props}
    />
  );
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  const size = React.useContext(CardSizeContext);

  return (
    <div
      data-slot="card-title"
      className={cn(
        "font-heading leading-snug font-medium",
        size === "sm" ? "text-sm" : "text-base",
        className,
      )}
      {...props}
    />
  );
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  );
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  const size = React.useContext(CardSizeContext);

  return (
    <div
      data-slot="card-content"
      className={cn("separator-inset", cardSpacing[size].section, className)}
      {...props}
    />
  );
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  const size = React.useContext(CardSizeContext);

  return (
    <>
      <Separator variant="full" className={cardSpacing[size].footerSeparator} />
      <div
        data-slot="card-footer"
        className={cn(
          "flex items-center rounded-b-xl bg-muted/50",
          cardSpacing[size].footer,
          className,
        )}
        {...props}
      />
    </>
  );
}

export { Card, CardHeader, CardFooter, CardTitle, CardAction, CardDescription, CardContent };
